def savejl(n,rows):(W/n).write_text(''.join(json.dumps(r,ensure_ascii=False)+'\n' for r in rows),encoding='utf-8')
def stat(values):
 x=[v for v in values if isinstance(v,(float,int)) and not isinstance(v,bool) and math.isfinite(v)]
 return {'n':len(x),'mean':statistics.mean(x) if x else None,'median':statistics.median(x) if x else None,'sample_sd':statistics.stdev(x) if len(x)>1 else None,'min':min(x) if x else None,'max':max(x) if x else None}
def rate(n,d):return {'numerator':n,'denominator':d,'rate':n/d if d else None}
def acc(rows,n):
 correct=sum(x['verdict']=='correct' for x in rows);incorrect=sum(x['verdict']=='incorrect' for x in rows);ne=n-correct-incorrect;task=sum(x['validated_task_success'] for x in rows)
 return {'fixed_n':n,'correct_n':correct,'incorrect_n':incorrect,'not_evaluable_n':ne,'conditional_accuracy':correct/(correct+incorrect) if correct+incorrect else None,'conditional_n':correct+incorrect,'fixed_content_success':rate(correct,n),'fixed_validated_task_success':rate(task,n)}

